rows[89890]={title={{23,1378973906},"으스스한 가시불꽃 우상"},description={{335,2082008846},"하이 엘프는 아마니 트롤과 전쟁을 벌일 당시, 트롤의 무기에 깃든 주술이 어째서 자신들의 무기보다 강력한지 알 수 없었습니다. 결국 트롤 주문술사로부터 잔자를 포함한 고대 지식을 훔쳐내 이와 같은 우상을 이용하여, 자신들만의 트롤 주술을 만들어낼 수 있게 되었습니다."}}
rows[89891]={title={{14,460713694},"진사 장신구"},description={{233,1927005050},"화산의 붉은색 독성 광물로 만들어진 작은 징표입니다. 뒷면에는 이것이 한때 독사 민로스의 소유였음을 나타내는 글귀가 새겨져 있습니다. 따개비의 흔적이 바다 속에 오랜 기간 머물렀음을 알려줍니다."}}
rows[89892]={title={{10,997695517},"폭탄 투척"},description={{49,1415805022},"주위의 기름 분출샘에 폭탄을 던져 발화시킵니다."}}
rows[89893]={title={{22,1041799556},"엘드레탈라스 동전"},description={{171,974790533},"한때 명가의 도시였던 여왕 아즈샤라의 도시에서, 비전술사들은 타락을 거듭한 끝에 결국 세계의 분리 속에 사라지고 말았습니다. 현재 남은 것은 혈투의 전장이라 알려진 폐허뿐입니다."}}
rows[89894]={title={{16,1133325302},"부서진 넓은날창"},description={{227,1800081782},"엘프 공성 무기에서 발사된 커다란 삼중날 투사체의 파편입니다. 지금은 수리검 투척기가 널리 쓰이지만, 이 조각의 정교한 장식은 나이트 엘프의 관점에서도 아주 오래된 형태입니다."}}
rows[89895]={title={{22,887626678},"뒤틀린 국석 껍질"},description={{197,1819031790},"국석은 지금은 멸종한 껍질 있는 연체동물의 화석입니다. 껍질은 창처럼 길기도 했고, 다양한 방식으로 감겨 있기도 했습니다. 이 국석은 작은 종의 화석이지만, 매우 큰 국석도 있습니다."}}
rows[89896]={title={{17,1436021735},"녹색용 반지"},description={{204,177146431},"이세라의 배우자인 에라니쿠스의 모습을 본떠 만들어졌습니다. 에라니쿠스는 에메랄드의 악몽에서 타락 속으로 사라졌다가 후에 다시 나타났습니다. 반지 속에 '안두 팔라 도르!'라는 글귀가 보입니다."}}
