rows[90416]={title={{19,1477836054},"탑승 인원 전체 내보내기"}}
rows[90417]={title={{21,112314019},"곡식 보급소 오염"},description={{42,165698979},"검은바위 나락의 곡식 보급소를 독으로 오염시킵니다."}}
rows[90418]={title={{15,2027707163},"화산 하늘상자"}}
rows[90419]={title={{27,2012042537},"아이언스타의 석화 방패"},description={{163,1754740261},"전설에 따르면 검은무쇠 드워프의 영주 아이언스타는 신성한 하이 엘프 나무로 자신의 방패를 깎은 다음, 마법을 부여하여 돌처럼 단단하게 만들었다고 합니다."}}
rows[90420]={title={{20,1590834727},"해골모양 화분"},description={{187,122173122},"숲트롤은 식물과 밀접한 관계를 맺고 있습니다. 몸에서 이끼나 조류와 같은 작은 초목이 자라기도 하여, 피부가 특이한 녹색을 띄고 있습니다."}}
rows[90421]={title={{26,401834601},"비취 장식 팔찌"},description={{333,1771033574},"트롤 동전과 광을 낸 비취 조각을 은 사슬로 연결한 팔찌입니다. 트롤은 금으로 된 장신구를 선호하기에 은 장신구는 다른 종족으로부터 탈취한 것으로 추측되며, 따라서 이 팔찌는 보기보다 오래되지 않은 물건입니다. 특이한 모양의 동전에는 음흉한 눈빛의 트롤 여성들이 그려져 있습니다."}}
rows[90422]={title={{15,330545574},"거대한 회전베기"}}
rows[90423]={title={{19,594540158},"가즈릴라 조각상"},description={{310,956267305},"모래의 트롤들은 줄파락 안에 있는 신성한 웅덩이에서 거대한 흰색 히드라를 소환하여 신으로 숭배했습니다. 가즈릴라의 비늘에는 전기가 흐르고 있어, 작은 조각상임에도 활력이 느껴집니다. 줄파락 안에서는 전설의 히드라를 주제로 한 건축물과 장식을 많이 볼 수 있습니다."}}
