rows[90448]={title={{6,881017395},"독"},description={"^a growing cloud of poison deals ([%+%-]?%d[%d,.%+%-to –]*) nature damage to all enemies within 12 yards%.$","자라나는 독구름으로 12미터 반경 내에 있는 모든 적에게 \0311\031의 자연 피해를 입힙니다.",{0},{1}}}
