rows[90504]={title={{31,670871034},"호루즈 킬크로우의 긁힌 방패"},description={{177,1288451806},"호루즈와 그의 동료들이 거대 고룡 칼드리고스와 맞서 싸울 때, 명망 있는 전사 호루즈는 그만 중대한 실수를 저지르고 자신의 목숨을 대가로 치르게 됩니다. 바로 용 뒤에 서 있었던 것이죠. 절대 그러면 안 됩니다."}}
rows[90505]={title={{36,970390617},"아이템 - 주술사 정기 보너스"},description={"^reduces the cast time of your lightning bolt spell by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","번개 화살의 시전 시간이 \0311\031%만큼 감소합니다.",{0},{1}}}
rows[90506]={title={{37,1261804561},"어둠 사제 아눈드의 그을린 지팡이"},description={{107,626705123},"비전 숨결로 새까맣게 타버린 나무 지팡이입니다. 무기를 사용하던 자 역시 그와 같은 운명을 맞았으리라 생각됩니다."}}
rows[90507]={title={{11,92652640},"죽음 포식자"},aura={"^attack power increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","전투력 \0311\031%만큼 증가",{0},{1}}}
