rows[90509]={title={{29,1370564564},"서슬깃 차를가의 홀"},description={{307,2103753976},"드워프의 유물 조각과 함께 발견되었지만, 분명히 드워프가 아닌 가시멧돼지가 만든 물건입니다. 한때 서슬깃 차를가가 직접 사용하던 홀로 보입니다. 영웅들이 가시덩굴 우리를 정복하면서 드워프의 손에 들어갔을지도 모릅니다."}}
rows[90510]={title={{21,336052630},"퀘스트 투명 상태 25"}}
rows[90511]={title={{31,712617013},"투명 상태 감지 퀘스트 25"}}
rows[90518]={title={{27,2060123131},"앵거포지의 미스릴 목걸이"},description={{207,1270659692},"앵거포지 일족은 검은무쇠 드워프 중에서도 오랜 역사를 지니고 있습니다. 지금도 검은바위 나락에서 검은무쇠 군대를 이끌고 있는 사령관 앵거포지의 선조인 영주 앵거포지가 착용했던 목걸이입니다."}}
rows[90519]={title={{26,1405768638},"섀도포지의 해골 지팡이"},description={{300,7585927},"섀도포지 가문은 검은무쇠 부족의 역사에 기나긴 흔적을 남겼습니다. 전해지는 이야기로는, 무쇠 영주 섀도포지가 수많은 동족을 고문하고 살해한 잔인한 폭군이었다고 합니다. 그는 흑마법사로 알려졌지만 어떤 이들은 그가 드워프 최초의 주술사였다는 소문을 굳게 믿고 있습니다."}}
rows[90520]={title={{15,272259590},"비전 과부하"}}
rows[90521]={title={{15,1968409189},"노움 태엽돌이"},description={{223,1994311362},"기계노움은 티탄이 하인이자 관리인처럼 부리려고 만든 종족으로, 토석인과 매우 유사합니다. 본래 임무에 더는 충실하지 않고 당신을 기꺼이 따르는 점으로 미루어 볼 때, 이 기계노움은 어딘가 고장이 난 듯합니다."}}
rows[90522]={title={{11,57732735},"물 보호막"},description={"^absorbs ([%+%-]?%d[%d,.%+%-to –]*) damage, if the water shell is broken, it wil explode and inflict ([%+%-]?%d[%d,.%+%-to –]*) frost damage to enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards%.$","\0311\031의 피해를 흡수하고 파괴되면 폭발하여 \0313\031미터 반경 내의 적에게 \0312\031의 냉기 피해를 입힙니다.",{0,0,0},{1,2,3}},aura={"^absorbs ([%+%-]?%d[%d,.%+%-to –]*) damage%. causes a water splash if broken%.$","\0311\031의 피해 흡수\010파괴 시 물 튀기기 발생",{0},{1}}}
rows[90523]={title={{15,1968409189},"노움 태엽돌이"},description={{55,755200133},"노움 태엽돌이를 소환하거나 소환 해제합니다."}}
rows[90524]={title={{15,697451022},"물 폭발"},description={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) frost damage to enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards%.$","\0312\031미터 주변의 적에게 \0311\031의 냉기 피해를 입힙니다.",{0,0},{1,2}},aura={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*) frost damage to enemies within ([%+%-]?%d[%d,.%+%-to –]*) yards%.$","\0312\031미터 주변의 적에게 \0311\031의 냉기 피해를 입힙니다.",{0,0},{1,2}}}
