rows[90546]={title={{8,358253552},"미련퉁이의 보호"},description={{69,1946286929},"힘센 미련퉁이의 보호를 받습니다. 미련퉁이가 움직이는 동안에는 헬릭스가 죽지 않습니다."},aura={{59,1271378413},"미련퉁이의 보호를 받는 동안에는 헬릭스가 죽지 않음"}}
rows[90550]={title={{14,14523637},"비전 탄막"},description={{72,862104315},"적 대상에게 여러 발의 화살을 발사하여 비전 피해를 입힙니다."}}
rows[90551]={title={{18,2017975183},"압도적인 힘"},description={{72,1887263342},"오크의 마법을 방출해 적 대상에게 비전 피해를 입힙니다."},aura={"^deals ([%+%-]?%d[%d,.%+%-to –]*) damage every second to the enemy%.$","1초마다 적에게 \0311\031의 피해",{0},{1}}}
rows[90553]={title={{29,1810331},"산왕의 성배"},description={{429,454588499},"무수히 많은 보석 장식 외에도, 고대에 행해졌던 산왕의 승천 의식을 축하하는 룬이 그야말로 성배를 뒤덮고 있습니다. 이 성배에 든 술을 마시는 것도 의식의 일부였으며, 룬을 계속 읽어나가니 여성 드워프 전사들이 추는 \"칼춤\"을 묘사한 대목도 나옵니다. 양식화되어 있는 동시에 모의 전투 같기도 한 이 춤은 드워프 문명이 보다 덜 세련됐던 시절에 치러졌던 피비린내나는 결투가 그 기원인 듯합니다."}}
