rows[90607]={title={{18,186909156},"무기력의 저주"},description={"^decreases the magical damage dealt by the target by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%.$","\0312\031 동안 대상의 마법 공격력을 \0311\031%만큼 감소시킵니다.",{0,1},{1,2}},aura={"^magical damage dealt is reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","마법 공격력 \0311\031%만큼 감소",{0},{1}}}
rows[90608]={title={{29,1078262431},"진로크 - 세상의 파괴자"},description={{429,1279073451},"조사한 바에 따르면 이 거대한 무기는 줄구룹에 있는 영혼약탈자 학카르의 수많은 보물 중 하나였습니다. 학카르는 수년 전 쓰러졌고 이 칼은 분리되기 전까지 강력한 전사와 성기사의 손을 거쳐왔습니다. 칼을 재련하는 데 성공한 것은 놀랄 만한 일이나, 한편으로는 걱정스럽기도 합니다. 만약 세상의 파괴자가 다시 나타난다면 그의 배후에는 영혼약탈자가 존재할 것이기 때문입니다."}}
rows[90609]={title={{27,552320276},"작은 분홍 진주 목띠"},description={{284,769974857},"진주 알은 약간 작지만 무려 마흔 두 개의 알을 사용해 독특한 디자인을 이루고 있습니다. 오팔의 흰색이나 희귀한 검은 조개 진주의 색이 아닌, 장미빛 분홍색을 띄고 있으며 마무리 장식에는 조개껍질이 사용되었습니다."}}
rows[90610]={title={{27,824349456},"소형 유리 동물이 담긴 상자"},description={{313,1923480309},"엘프의 유리 야생 동물이 보관된 상자는 상당히 주목할 만한 발굴품입니다. 몇몇 동물들은 자연스럽게 이가 빠지거나 금이 가 있지만, 사슴의 머리 부분은 고의로 절단된 듯한 모습입니다. 상자 바닥에는 'T'라는 머리글자가 새겨져 있습니다."}}
rows[90611]={title={{20,63993235},"금이 간 수정 약병"},description={{247,39503679},"약병에 묶인 고급 피지에는 다음과 같은 글이 적혀 있습니다. '사랑하는 P, 이제 다시는 함께할 수 없기에 전 이 거미독을 마시려 합니다. 만약 이 글을 보게 된다면 당신도 저와 같이 하길 바랍니다. 엘룬께서 당신을 보살펴 주시기를.'"}}
rows[90612]={title={{17,620212999},"자비우스의 홀"},description={{323,1412899896},"자비우스는 고대의 전쟁 당시 나이트 엘프 부족에 수없이 많은 악마를 몰고 왔습니다. 결국 말퓨리온 스톰레이지가 자비우스를 저지하고 그를 쓰러뜨렸으나, 후에 살게라스는 자비우스의 영혼을 고문하고 그에게 뒤틀린 육체를 선사하여 최초의 사티로스로 만들었습니다."}}
rows[90614]={title={{20,1561538719},"칼도레이 풍경"},description={{262,428709841},"풍부하게 장식된 다양한 길이의 청동관이 덩굴 형태의 청동줄에 연결되어 있습니다. 바람이 불지 않아도 고유의 음악을 연주하는 듯한 마법의 풍경입니다."}}
rows[90615]={title={{37,214155078},"마지막 한 골: 캐릭터 지진"}}
rows[90616]={title={{29,488172462},"아즈샤라 여왕의 화장복"},description={{300,1959007158},"아즈샤라가 가장 아름다운 나이트 엘프였다는 사실에는 의심의 여지가 없습니다. 하지만 이 요란스러운 색상의 의상으로 미루어볼 때, 그녀의 심미안은 불행하게도 남자 형제들과 비슷한 수준에 머물렀던 것 같습니다. '아즈샤라는 단 하나였으며, 앞으로도 단 하나일 것입니다.'"}}
rows[90617]={title={{20,2061443026},"깃털 달린 랩터 팔"},description={{306,1266429991},"탐험가 연맹에는 새들의 조상이 이 랩터와 같은 공룡일 거라고 믿는 자들이 있습니다. 팔에 달린 깃털은 두 가지 동물 간의 잃어버린 연결 고리를 보여줍니다. 하지만 이 생물은 단지 아제로스를 뒤덮은 낯선 괴물 중 하나에 불과할 수도 있습니다."}}
rows[90618]={title={{20,681437651},"흉포한 고대 물고기"},description={{264,244952522},"무거운 골판이 물고기 뼈를 보호하고 있으며 턱에는 수백 개의 가시 모양 이빨이 여러 줄로 나 있습니다. 어떤 사람들은 물고기 화석이 바다로부터 수백 킬로미터나 떨어진 내륙 지역에서 발견된다는 점을 근거로, 한때 모든 대륙이 바다로 덮여 있었다고 믿기도 합니다."}}
rows[90619]={title={{17,1866911802},"화석 랩터"},description={{105,206099676},"기괴한 마법으로 해골을 모두 맞추자 동물이 되살아났습니다."}}
