rows[90831]={title={{13,653940883},"기괴한 채찍"},description={{180,1086673621},"굴단의 힘이 점점 커지자 흑마법사들의 위상도 점점 높아졌습니다. 이 서큐버스의 채찍은 여러 생물의 가죽을 꼬아 만들었는데, 그중에는 사람의 가죽도 있는 듯합니다."}}
rows[90832]={title={{19,853924554},"유약 기와"},description={{259,973877743},"유약 기와는 드레노어의 요새나 접견실의 벽과 바닥을 장식하는 데 주로 사용되었습니다. 녹색과 황색 유약을 바른 표면에 묘사된 동물의 무리를 보고 있으면 나그란드의 풍경이 떠오릅니다. 가장자리는 검은색과 갈색의 장기판 무늬로 장식되어 있습니다."}}
rows[90833]={title={{18,1045742077},"해골 잔"},description={{122,2014422463},"섬뜩해 보이는 컵이지만 구조상 눈구멍으로 액체가 계속 흘러나오는 문제점이 있습니다. 갈증이 납니다..."}}
