rows[90860]={title={{26,999258329},"진귀한 나무로 조각한 하프"},description={{213,1620594731},"수금처럼 한 손에 들고 연주하는 작은 하프입니다. 나무로 만든 깊은 울림통이 있고 일곱 가닥의 현이 조음 막대에 묶여 있습니다. 곡을 연주할 수는 있으나 애처롭고 구슬픈 소리만 날 것 같습니다."}}
rows[90861]={title={{26,1394645355},"이상한 은 문진"},description={{186,609342593},"드레나이가 사용하던 문진이 아니라면, 그 외의 용도는 전혀 알 수가 없습니다. 수은을 굳힌 덩어리로 한쪽 면이 평평하여 책상 위에 놓고 쓸 수 있습니다."}}
rows[90864]={title={{24,285604179},"나스레짐의 홀"},description={{236,2085371229},"공포의 군주로 알려진 나스레짐은 불타는 군단의 첩보요원이자 심문관으로 활동합니다. 그들은 전장에서는 강한 적이지만, 비열한 속임수로 여러 나라들을 이간질하길 좋아합니다."}}
